# Example: Implementing confidence-based UX tiers

def get_user_experience(prediction_confidence, prediction_value):
    if prediction_confidence >= 0.90:
        return {
            'action': 'auto_apply',
            'message': f'Applied: {prediction_value}',
            'ui_element': 'success_banner'
        }
    elif prediction_confidence >= 0.70:
        return {
            'action': 'suggest',
            'message': f'Suggested: {prediction_value} ({int(prediction_confidence*100)}% confident)',
            'ui_element': 'approval_button'
        }
    else:
        return {
            'action': 'human_review',
            'message': 'Low confidence - manual review required',
            'ui_element': 'review_queue'
        }
